//! Independent CPU evidence that checked CSR triplet coalescing rejects
//! non-finite values generated by finite duplicate entries.

use sonium_qa::QaResult;
use sonium_solvers::{CsrMatrix, SolverError, TripletMatrix};
use std::time::Instant;

const CASE_ID: &str = "solvers.csr-generated-nonfinite.v1";
const INPUT_CHECKSUM: &str = "analytic/deterministic-fixture:csr-generated-nonfinite-v1";
const TOLERANCE: f64 = 1.0e-12;

fn run() -> Result<(f64, f64, f64, f64, f64, f64, f64), String> {
    let finite = CsrMatrix::try_from_triplets(1, 1, vec![(0, 0, 1.25_f64), (0, 0, 2.75_f64)])
        .map_err(|error| format!("finite duplicate CSR construction failed: {error:?}"))?;
    let action = finite.matvec(&[1.0])[0];
    let finite_action_error = (action - 4.0).abs();
    if !finite_action_error.is_finite() || finite_action_error > TOLERANCE {
        return Err(format!(
            "finite duplicate CSR action error {finite_action_error} exceeds tolerance"
        ));
    }

    let overflowing = CsrMatrix::try_from_triplets(1, 1, vec![(0, 0, f64::MAX), (0, 0, f64::MAX)]);
    let generated_nonfinite_rejection = usize::from(matches!(
        overflowing,
        Err(SolverError::OperationFailed {
            operation: "CSR triplet construction",
            ref reason,
        }) if reason.contains("duplicate coalescing generated non-finite")
    ));
    if generated_nonfinite_rejection != 1 {
        return Err("CSR triplet construction accepted an overflow-generated value".into());
    }

    let left = CsrMatrix::from_raw_parts(1, 1, vec![0, 1], vec![0], vec![2.0_f64]);
    let right = CsrMatrix::from_raw_parts(1, 1, vec![0, 1], vec![0], vec![3.0_f64]);
    let product = left
        .try_matmul(&right)
        .map_err(|error| format!("finite CSR matmul failed: {error:?}"))?;
    let finite_matmul_error = (product.get(0, 0) - 6.0).abs();
    if !finite_matmul_error.is_finite() || finite_matmul_error > TOLERANCE {
        return Err(format!(
            "finite CSR matmul error {finite_matmul_error} exceeds tolerance"
        ));
    }

    let overflowing = CsrMatrix::from_raw_parts(1, 1, vec![0, 1], vec![0], vec![f64::MAX]);
    let matmul_rejection = usize::from(matches!(
        overflowing.try_matmul(&right),
        Err(SolverError::OperationFailed {
            operation: "CSR matmul",
            ref reason,
        }) if reason.contains("non-finite")
    ));
    if matmul_rejection != 1 {
        return Err("CSR matmul accepted an overflow-generated value".into());
    }

    let malformed_lengths = TripletMatrix {
        rows: vec![0],
        cols: Vec::new(),
        values: vec![1.0_f64],
        num_rows: 1,
        num_cols: 1,
    };
    let triplet_dimension_rejection = usize::from(matches!(
        malformed_lengths.try_to_csr(),
        Err(SolverError::DimensionMismatch {
            expected: 1,
            got: 0,
        })
    ));
    if triplet_dimension_rejection != 1 {
        return Err("TripletMatrix accepted mismatched public buffers".into());
    }

    let out_of_range = TripletMatrix {
        rows: vec![1],
        cols: vec![0],
        values: vec![1.0_f64],
        num_rows: 1,
        num_cols: 1,
    };
    let triplet_index_rejection = usize::from(matches!(
        out_of_range.try_to_csr(),
        Err(SolverError::OperationFailed {
            operation: "CSR triplet construction",
            ..
        })
    ));
    if triplet_index_rejection != 1 {
        return Err("TripletMatrix accepted an out-of-range coordinate".into());
    }

    let overflowing_triplets = TripletMatrix {
        rows: vec![0, 0],
        cols: vec![0, 0],
        values: vec![f64::MAX, f64::MAX],
        num_rows: 1,
        num_cols: 1,
    };
    let triplet_generated_nonfinite_rejection = usize::from(matches!(
        overflowing_triplets.try_to_csr(),
        Err(SolverError::OperationFailed {
            operation: "CSR triplet construction",
            ref reason,
        }) if reason.contains("duplicate coalescing generated non-finite")
    ));
    if triplet_generated_nonfinite_rejection != 1 {
        return Err("TripletMatrix accepted an overflow-generated duplicate".into());
    }

    Ok((
        finite_action_error,
        generated_nonfinite_rejection as f64,
        finite_matmul_error,
        matmul_rejection as f64,
        triplet_dimension_rejection as f64,
        triplet_index_rejection as f64,
        triplet_generated_nonfinite_rejection as f64,
    ))
}

fn main() {
    let started = Instant::now();
    match run() {
        Ok((
            finite_action_error,
            generated_nonfinite_rejection,
            finite_matmul_error,
            matmul_rejection,
            triplet_dimension_rejection,
            triplet_index_rejection,
            triplet_generated_nonfinite_rejection,
        )) => {
            let result = QaResult::passed(CASE_ID)
                .requested_backend("cpu")
                .actual_backend("cpu")
                .reference("independent CSR and TripletMatrix action/admission oracles")
                .input_checksum(INPUT_CHECKSUM)
                .reference_checksum(INPUT_CHECKSUM)
                .dimension("1x1 CSR and TripletMatrix finite, malformed, and overflowing duplicate fixtures")
                .tolerance("finite action/matmul errors <= 1e-12; one rejection at each checked TripletMatrix boundary")
                .metric("finite_duplicate_action_error", finite_action_error)
                .metric(
                    "generated_nonfinite_rejection",
                    generated_nonfinite_rejection,
                )
                .metric("finite_matmul_error", finite_matmul_error)
                .metric("matmul_generated_nonfinite_rejection", matmul_rejection)
                .metric("triplet_dimension_rejection", triplet_dimension_rejection)
                .metric("triplet_index_rejection", triplet_index_rejection)
                .metric(
                    "triplet_generated_nonfinite_rejection",
                    triplet_generated_nonfinite_rejection,
                )
                .maximum("finite_duplicate_action_error", TOLERANCE)
                .maximum("finite_matmul_error", TOLERANCE)
                .minimum("generated_nonfinite_rejection", 1.0)
                .minimum("matmul_generated_nonfinite_rejection", 1.0)
                .minimum("triplet_dimension_rejection", 1.0)
                .minimum("triplet_index_rejection", 1.0)
                .minimum("triplet_generated_nonfinite_rejection", 1.0)
                .elapsed_ms(started.elapsed().as_millis() as u64);
            println!("QA_RESULT: {}", result.to_json_line().expect("QA JSON"));
            println!("SUCCESS");
        }
        Err(error) => {
            let result = QaResult::failed(CASE_ID, error.clone())
                .elapsed_ms(started.elapsed().as_millis() as u64);
            println!("QA_RESULT: {}", result.to_json_line().expect("QA JSON"));
            eprintln!("FAILED: {error}");
            std::process::exit(1);
        }
    }
}
